/* Mandatory CSS rule to prevent display overrides on hidden elements */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #2d3748;
  --color-board: #1a202c;
  --color-wood: #c05621;
  --color-wood-dark: #9c4221;
  --color-wood-light: #dd6b20;
  --color-card: #f7fafc;
  --color-card-border: #4a5568;
  --color-text: #2d3748;
  --color-text-light: #718096;
  --color-accent: #3182ce;
  --color-accent-hover: #2b6cb0;
  --color-occupied: #38a169;
  --color-occupied-hover: #e53e3e;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--color-bg);
  font-family: var(--font-family);
  font-size: 16px;
  color: var(--color-text);
  padding: 16px;
}

.classroom-app {
  background: var(--color-card);
  border: 4px solid var(--color-card-border);
  box-shadow: 8px 8px 0px rgba(0, 0, 0, 0.4);
  width: 100%;
  max-width: 640px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  text-align: center;
}

.app-title {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -0.5px;
  color: var(--color-text);
}

.app-subtitle {
  font-size: 1rem;
  color: var(--color-text-light);
  margin-top: 4px;
}

.control-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  background: #edf2f7;
  padding: 16px;
  border: 2px solid var(--color-card-border);
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 200px;
}

.input-label {
  font-size: 1rem;
  font-weight: 700;
}

.name-input {
  font-size: 1rem;
  padding: 10px 12px;
  border: 2px solid var(--color-card-border);
  background: #fff;
  color: var(--color-text);
  outline: none;
}

.name-input:focus-visible {
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(49, 130, 206, 0.3);
}

.counter-box {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: center;
  min-width: 120px;
}

.counter-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-light);
}

.counter-value {
  font-size: 1.35rem;
  font-weight: 800;
  color: var(--color-accent);
}

.board-frame {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 16px;
  background: #e2e8f0;
  border: 2px solid var(--color-card-border);
}

.blackboard {
  background: var(--color-board);
  color: #a0aec0;
  border: 3px solid #4a5568;
  padding: 8px 12px;
  text-align: center;
  letter-spacing: 1.5px;
  font-size: 0.85rem;
  font-weight: 700;
  box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.6);
}

.seating-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.desk-btn {
  appearance: none;
  background: #fff;
  border: 3px solid var(--color-card-border);
  box-shadow: 3px 3px 0px rgba(0, 0, 0, 0.25);
  padding: 12px 6px;
  min-height: 80px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  position: relative;
  text-align: center;
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.desk-btn:hover {
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.3);
  border-color: var(--color-accent);
}

.desk-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px rgba(0, 0, 0, 0.2);
}

.desk-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.desk-btn.empty {
  background: #edf2f7;
}

.desk-btn.empty .desk-status {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--color-text-light);
}

.desk-btn.empty .desk-number {
  font-size: 0.75rem;
  color: #a0aec0;
  margin-top: 2px;
}

.desk-btn.seated {
  background: #c6f6d5;
  border-color: #276749;
}

.desk-btn.seated:hover {
  background: #fed7d7;
  border-color: #9b2c2c;
}

.desk-btn.seated .student-avatar {
  font-size: 1.1rem;
  margin-bottom: 2px;
}

.desk-btn.seated .student-name {
  font-size: 0.9rem;
  font-weight: 700;
  color: #22543d;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 0 4px;
}

.desk-btn.seated:hover .student-name {
  color: #9b2c2c;
}

.instruction-hint {
  text-align: center;
  font-size: 0.9rem;
  color: var(--color-text-light);
}

@media (max-width: 480px) {
  .seating-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .classroom-app {
    padding: 16px;
  }

  .desk-btn {
    min-height: 70px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const TOTAL_SEATS = 12;
  const seats = Array(TOTAL_SEATS).fill(null);

  const seatingGrid = document.getElementById('seating-grid');
  const nameInput = document.getElementById('student-name-input');
  const counterDisplay = document.getElementById('seat-counter');

  function updateCounter() {
    const filledCount = seats.filter(name => name !== null).length;
    counterDisplay.textContent = `${filledCount} / ${TOTAL_SEATS}`;
  }

  function renderDesk(index) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'desk-btn';
    button.dataset.index = index;

    updateDeskElement(button, seats[index], index);

    button.addEventListener('click', () => handleDeskClick(index));
    return button;
  }

  function updateDeskElement(button, studentName, index) {
    const deskNumber = index + 1;
    button.innerHTML = '';

    if (studentName === null) {
      button.className = 'desk-btn empty';
      button.setAttribute('aria-label', `Desk ${deskNumber}: Empty. Click to seat student.`);

      const statusSpan = document.createElement('span');
      statusSpan.className = 'desk-status';
      statusSpan.textContent = 'Empty';

      const numSpan = document.createElement('span');
      numSpan.className = 'desk-number';
      numSpan.textContent = `Desk ${deskNumber}`;

      button.appendChild(statusSpan);
      button.appendChild(numSpan);
    } else {
      button.className = 'desk-btn seated';
      button.setAttribute('aria-label', `Desk ${deskNumber}: Seated by ${studentName}. Click to clear.`);

      const avatarSpan = document.createElement('span');
      avatarSpan.className = 'student-avatar';
      avatarSpan.setAttribute('aria-hidden', 'true');
      avatarSpan.textContent = '🧑';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'student-name';
      nameSpan.textContent = studentName;

      button.appendChild(avatarSpan);
      button.appendChild(nameSpan);
    }
  }

  function handleDeskClick(index) {
    const currentStudent = seats[index];

    if (currentStudent !== null) {
      // Clicking seated desk clears it
      seats[index] = null;
    } else {
      // Clicking empty desk seats student
      const enteredName = nameInput.value.trim();
      if (!enteredName) {
        nameInput.focus();
        return;
      }
      seats[index] = enteredName;
      nameInput.value = '';
    }

    const deskBtn = seatingGrid.querySelector(`button[data-index="${index}"]`);
    if (deskBtn) {
      updateDeskElement(deskBtn, seats[index], index);
    }
    updateCounter();
  }

  // Initialize 3x4 grid
  for (let i = 0; i < TOTAL_SEATS; i++) {
    seatingGrid.appendChild(renderDesk(i));
  }
  updateCounter();
});
